create index assignments_worker_id_idx on public.assignments(worker_id);
create index audit_log_actor_id_idx on public.audit_log(actor_id);
create index corrections_decided_by_idx on public.corrections(decided_by);
create index corrections_event_id_idx on public.corrections(event_id);
create index corrections_requester_id_idx on public.corrections(requester_id);
create index invitations_agency_id_idx on public.invitations(agency_id);
create index notes_author_id_idx on public.notes(author_id);
create index schedule_requests_requester_id_idx on public.schedule_requests(requester_id);
create index schedules_agency_id_idx on public.schedules(agency_id);
create index schedules_recipient_id_idx on public.schedules(recipient_id);
create index visits_recipient_id_idx on public.visits(recipient_id);
create index visits_schedule_id_idx on public.visits(schedule_id);
create index visits_worker_id_idx on public.visits(worker_id);
alter policy agency_read on public.agencies using(id=(select private.my_agency()) or exists(select 1 from public.invitations i where i.agency_id=agencies.id and i.user_id=(select auth.uid()) and i.status='pending'));
alter policy profile_read on public.profiles using(id=(select auth.uid()) or ((select private.is_admin()) and exists(select 1 from public.memberships m where m.user_id=profiles.id and m.agency_id=(select private.my_agency()) and m.active)));
alter policy member_read on public.memberships using(user_id=(select auth.uid()) or (agency_id=(select private.my_agency()) and (select private.is_admin())));
alter policy invite_read on public.invitations using(user_id=(select auth.uid()) or (agency_id=(select private.my_agency()) and (select private.is_admin())));
alter policy recipient_read on public.recipients using(private.sees_recipient(id));
alter policy assignment_read on public.assignments using(private.sees_recipient(recipient_id));
alter policy schedule_read on public.schedules using(agency_id=(select private.my_agency()) and (worker_id=(select auth.uid()) or (select private.is_admin())));
alter policy schedule_request_read on public.schedule_requests using(exists(select 1 from public.schedules s where s.id=schedule_requests.schedule_id and s.agency_id=(select private.my_agency()) and (s.worker_id=(select auth.uid()) or (select private.is_admin()))));
alter policy visit_read on public.visits using(private.sees_visit(id));
alter policy event_read on public.visit_events using(private.sees_visit(visit_id));
alter policy location_read on public.locations using(private.sees_visit(visit_id));
alter policy note_read on public.notes using(private.sees_visit(visit_id));
alter policy case_read on public.cases using(private.sees_visit(visit_id) and ((select private.is_admin()) or status<>'candidate'));
alter policy correction_read on public.corrections using(private.sees_visit(visit_id));
alter policy audit_read on public.audit_log using(agency_id=(select private.my_agency()) and (select private.is_admin()));
